begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at)values('f1300000-0000-0000-0000-000000000001','business-owner@test.invalid',now()),('f1300000-0000-0000-0000-000000000002','business-admin@test.invalid',now());
insert into public.platform_admins(user_id)values('f1300000-0000-0000-0000-000000000002');
insert into public.tenants(id,name,slug)values('f1301000-0000-0000-0000-000000000001','Delete Business','delete-business-130'),('f1301000-0000-0000-0000-000000000002','Keep Business','keep-business-130'),('f1301000-0000-0000-0000-000000000003','Empty Business','empty-business-130');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000001','owner'),('f1301000-0000-0000-0000-000000000002','f1300000-0000-0000-0000-000000000001','owner');
insert into public.properties(id,tenant_id,name,property_type)values('f1302000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','Delete Hotel A','hotel'),('f1302000-0000-0000-0000-000000000002','f1301000-0000-0000-0000-000000000001','Delete Hotel B','hotel'),('f1302000-0000-0000-0000-000000000003','f1301000-0000-0000-0000-000000000002','Keep Hotel','hotel');
insert into public.guests(id,tenant_id,full_name)values('f1303000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','Unlinked business guest'),('f1303000-0000-0000-0000-000000000002','f1301000-0000-0000-0000-000000000002','Other business guest');
insert into public.roles(id,tenant_id,key,name)values('f1304000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','delete-custom','Custom role');
insert into public.role_permissions(role_id,permission_key)values('f1304000-0000-0000-0000-000000000001','reservations.read');
insert into public.staff_invitations(id,tenant_id,email,tenant_role,grants)values('f1305000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','invite@test.invalid','member','[{"property_id":"f1302000-0000-0000-0000-000000000001","role_key":"manager"}]');
insert into public.staff_commands(tenant_id,request_id,action,payload,result_id)values('f1301000-0000-0000-0000-000000000001',gen_random_uuid(),'invite','{"property_id":"f1302000-0000-0000-0000-000000000001"}','f1305000-0000-0000-0000-000000000001');
insert into private.platform_commands(actor_id,request_id,payload,result)values('f1300000-0000-0000-0000-000000000002',gen_random_uuid(),'{"tenant":"f1301000-0000-0000-0000-000000000001"}','{"tenant_id":"f1301000-0000-0000-0000-000000000001"}');
insert into public.subscriptions(tenant_id,plan_id,status)select 'f1301000-0000-0000-0000-000000000001',id,'active'from public.plans where key='starter'on conflict(tenant_id)do update set status='active';
insert into public.staff_invitation_emails(tenant_id,invitation_id,request_id,invitation_version,requested_by,status,context)values('f1301000-0000-0000-0000-000000000001','f1305000-0000-0000-0000-000000000001',gen_random_uuid(),1,'f1300000-0000-0000-0000-000000000001','sent','{"hotel":"Delete Hotel A"}');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1300000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.platform_business_deletion_preview('f1301000-0000-0000-0000-000000000001')$$,'42501',null,'Ordinary owner cannot preview platform business deletion');
select throws_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002',gen_random_uuid(),1,'Delete Business','Local QA cleanup')$$,'42501',null,'Browser roles cannot spoof the platform actor in the backend mutator');
reset role;
select set_config('request.jwt.claim.sub','f1300000-0000-0000-0000-000000000002',true);
select is((public.platform_business_deletion_preview('f1301000-0000-0000-0000-000000000001')->>'hotel_total')::int,2,'Review includes every hotel in the business');
select is((public.platform_business_deletion_preview('f1301000-0000-0000-0000-000000000001')->>'guest_profiles')::int,1,'Review includes business guests not linked to a reservation');
select ok(public.platform_business_deletion_preview('f1301000-0000-0000-0000-000000000001')::text not like '%Unlinked business guest%','Review exposes counts without guest identities');
select throws_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002',gen_random_uuid(),999,'Delete Business','Local QA cleanup')$$,'40001',null,'Stale business confirmation is rejected');
select throws_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002',gen_random_uuid(),1,'Wrong name','Local QA cleanup')$$,'40001',null,'Exact business name is required');
-- A blocker at one hotel must leave the entire business unchanged.
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f1306000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','f1302000-0000-0000-0000-000000000002','1300000001','1300000002','managed:f1302000-0000-0000-0000-000000000002');
insert into private.whatsapp_credentials(property_id,credentials_ref,ciphertext)values('f1302000-0000-0000-0000-000000000002','managed:f1302000-0000-0000-0000-000000000002',repeat('a',80));
insert into public.conversations(id,tenant_id,property_id,connection_id,wa_contact_id)values('f1307000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','f1302000-0000-0000-0000-000000000002','f1306000-0000-0000-0000-000000000001','919000000130');
insert into public.messages(id,tenant_id,property_id,conversation_id,direction,type,body,status)values('f1308000-0000-0000-0000-000000000001','f1301000-0000-0000-0000-000000000001','f1302000-0000-0000-0000-000000000002','f1307000-0000-0000-0000-000000000001','out','text','Synthetic blocker','sending');
select throws_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002','f1309000-0000-0000-0000-000000000001',1,'Delete Business','Local QA cleanup')$$,'55000',null,'One hotel with an in-flight send blocks the whole business');
select is((select count(*)::int from public.properties where tenant_id='f1301000-0000-0000-0000-000000000001'and archived_at is null),2,'Blocked deletion freezes no hotel');
select is((select count(*)::int from private.business_deletions where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Blocked deletion creates no business job');
update public.messages set status='queued'where id='f1308000-0000-0000-0000-000000000001';
-- Metadata-only fixture. Physical file removal is covered through local Storage API QA.
insert into storage.objects(bucket_id,name)values('hotel-whatsapp-photos','f1302000-0000-0000-0000-000000000001/one.jpg'),('guest-documents','f1301000-0000-0000-0000-000000000001/f1302000-0000-0000-0000-000000000002/two.jpg'),('guest-documents','f1301000-0000-0000-0000-000000000001/legacy-upload.jpg');
select lives_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002','f1309000-0000-0000-0000-000000000001',1,'Delete Business','Local QA cleanup')$$,'Platform admin begins business deletion');
select is((select count(*)::int from private.hotel_deletions where tenant_id='f1301000-0000-0000-0000-000000000001'),2,'All hotels are included in durable child cleanup jobs');
select is((select status from public.tenants where id='f1301000-0000-0000-0000-000000000001'),'suspended','Business is frozen before Storage cleanup');
select is((select count(*)::int from private.whatsapp_credentials where property_id='f1302000-0000-0000-0000-000000000002'),0,'WhatsApp credentials are removed when deletion starts');
select throws_ok($$update public.tenants set status='active'where id='f1301000-0000-0000-0000-000000000001'$$,'55000',null,'Deleting business cannot be reopened');
select throws_ok($$insert into public.properties(tenant_id,name,property_type)values('f1301000-0000-0000-0000-000000000001','Escaped hotel','hotel')$$,'55000',null,'New hotel cannot escape the deletion snapshot');
select throws_ok($$insert into public.guests(tenant_id,full_name)values('f1301000-0000-0000-0000-000000000001','Late guest')$$,'55000',null,'Business guest creation is frozen');
select throws_ok($$update public.staff_invitations set grants='[]'where id='f1305000-0000-0000-0000-000000000001'$$,'55000',null,'Staff access changes are frozen');
select throws_ok($$insert into public.role_permissions(role_id,permission_key)values('f1304000-0000-0000-0000-000000000001','reservations.write')$$,'55000',null,'Custom role changes are frozen');
select is(public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002',gen_random_uuid(),1,'Delete Business','Local QA cleanup'),'f1309000-0000-0000-0000-000000000001'::uuid,'Begin retry reuses the existing business job');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')->>'state','files','Hotel cleanup waits for physical files');
select is((select count(*)::int from public.tenants where id='f1301000-0000-0000-0000-000000000001'),1,'Business account remains while files await cleanup');
select set_config('storage.allow_delete_query','true',true);
delete from storage.objects where name in('f1302000-0000-0000-0000-000000000001/one.jpg','f1301000-0000-0000-0000-000000000001/f1302000-0000-0000-0000-000000000002/two.jpg');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')->>'state','hotels','First hotel completes without editing frozen shared invitations');
select is((select count(*)::int from public.tenants where id='f1301000-0000-0000-0000-000000000001'),1,'Business remains until every hotel completes');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')->>'state','hotels','Second hotel completes');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')->>'state','files','Abandoned business document uploads also require physical cleanup');
select throws_ok($$insert into storage.objects(bucket_id,name)values('guest-documents','f1301000-0000-0000-0000-000000000001/late-upload.jpg')$$,'55000',null,'Old business document upload cannot recreate files during cleanup');
delete from storage.objects where bucket_id='guest-documents'and name='f1301000-0000-0000-0000-000000000001/legacy-upload.jpg';
select lives_ok($$select public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')$$,'Business record and business-owned graph are removed after hotels finish');
select is((select count(*)::int from public.tenants where id='f1301000-0000-0000-0000-000000000001'),0,'Business no longer appears in the directory');
select is((select count(*)::int from public.properties where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'All business hotels are removed');
select is((select count(*)::int from public.guests where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Unlinked business guest profiles are removed');
select is((select count(*)::int from public.staff_invitations where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Business invitations are removed');
select is((select count(*)::int from public.roles where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Custom roles and permissions are removed');
select is((select count(*)::int from private.platform_commands where result->>'tenant_id'='f1301000-0000-0000-0000-000000000001'),0,'Old business command payloads are removed');
select is((select count(*)::int from auth.users where id in('f1300000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')),2,'Owner and admin login accounts remain');
select is((select count(*)::int from public.properties where id='f1302000-0000-0000-0000-000000000003'),1,'Other business hotel remains');
select is((select count(*)::int from public.guests where id='f1303000-0000-0000-0000-000000000002'),1,'Other business guest remains');
select is((select count(*)::int from public.tenant_memberships where tenant_id='f1301000-0000-0000-0000-000000000002'and user_id='f1300000-0000-0000-0000-000000000001'),1,'Shared owner retains other business membership');
select is((select count(*)::int from public.platform_audit_logs where action='platform_business_deleted'and details->>'business_id'='f1301000-0000-0000-0000-000000000001'),1,'One minimal platform receipt remains');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000002')->>'state','complete','Finish retry is idempotent');
select throws_ok($$select public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000001','f1300000-0000-0000-0000-000000000001')$$,'42501',null,'Every resume rechecks platform membership');
select lives_ok($$select public.platform_business_deletion_begin('f1301000-0000-0000-0000-000000000003','f1300000-0000-0000-0000-000000000002','f1309000-0000-0000-0000-000000000003',1,'Empty Business','Local empty business QA cleanup')$$,'Business without hotels can be removed');
select is(public.platform_business_deletion_step('f1309000-0000-0000-0000-000000000003','f1300000-0000-0000-0000-000000000002')->>'state','complete','Empty business cleanup completes');
select is((select count(*)::int from public.subscriptions where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Business subscription row is removed');
select is((select count(*)::int from public.staff_invitation_emails where tenant_id='f1301000-0000-0000-0000-000000000001'),0,'Invitation email context and history are removed');
select is(public.platform_business_deletion_preview('f1301000-0000-0000-0000-000000000001')->>'state','complete','Completed business preview remains accessible from its receipt');
select *from finish();
rollback;
